import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
CADENCE = 10
MIN_W, MAX_W = 0.025, 0.12
_seen_date = None
_days_since = CADENCE


def ranks(x):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    if len(a) > 1:
        for i, (s, _) in enumerate(a):
            out[s] = (i + 1.0) / len(a)
    return out


def cap_weights(raw):
    # Projection onto the full-investment box; no cash sleeve.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    for _ in range(100):
        free = [s for s in UNIVERSE if MIN_W < w[s] < MAX_W]
        fixed = [s for s in UNIVERSE if s not in free]
        rem = 1.0 - sum(w[s] for s in fixed)
        z = sum(w[s] for s in free)
        if not free or z <= 0:
            break
        nw = dict(w)
        for s in free:
            nw[s] = rem * w[s] / z
        w = nw
        old = dict(w)
        for s in UNIVERSE:
            w[s] = min(MAX_W, max(MIN_W, w[s]))
        if max(abs(w[s] - old[s]) for s in UNIVERSE) < 1e-10:
            break
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
