import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
CADENCE = 10
MIN_W, MAX_W = 0.025, 0.12
_last_date = None
_days = CADENCE


def cs_rank(vals):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    if len(a) > 1:
        for i, (s, _) in enumerate(a):
            out[s] = (i + 1.0) / len(a)
    elif a:
        out[a[0][0]] = 1.0
    return out


def bounded_weights(raw):
    # Iterative projection preserves a complete, non-negative, full-investment vector.
    w = {s: max(1e-12, float(raw.get(s, 0.0))) for s in UNIVERSE}
    for _ in range(100):
        z = sum(w.values())
        w = {s: v / z for s, v in w.items()}
        nw = {s: min(MAX_W, max(MIN_W, v)) for s, v in w.items()}
        if max(abs(nw[s] - w[s]) for s in UNIVERSE) < 1e-10:
            w = nw
            break
        fixed = {s for s in UNIVERSE if nw[s] <= MIN_W + 1e-12 or nw[s] >= MAX_W - 1e-12}
        free = [s for s in UNIVERSE if s not in fixed]
        w = nw
        if not free:
            break
        rem = 1.0 - sum(w[s] for s in fixed)
        free_sum = sum(w[s] for s in free)
        for s in free:
            w[s] *= rem / max(free_sum, 1e-12)
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_date, _days
    account = get_account_dict()
    # Fixed benchmark universe: observation-only macro series are never traded.
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=100)
        if df is None or len(df) < 35:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df.close, dtype=float)
        h = np.asarray(df.high, dtype=float)
        l = np.asarray(df.low, dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        data[s] = (c, h, l, r, str(df.iloc[-1].date))
    if len(data) < 12:
